<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Banyan Tree — Aerial Root Study</title>

  <style>
    :root {
      color-scheme: dark;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      background:
        radial-gradient(circle at 52% 38%, #29382c 0%, #152119 42%, #09100d 100%);
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      touch-action: none;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .vignette {
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at center, transparent 48%, rgba(2, 7, 5, 0.42) 100%);
    }

    .panel {
      position: fixed;
      top: clamp(24px, 5vw, 64px);
      left: clamp(24px, 5vw, 72px);
      width: min(360px, calc(100vw - 48px));
      color: #e8eadc;
      pointer-events: none;
      text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
    }

    .eyebrow {
      margin: 0 0 12px;
      color: #aebba5;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 0.28em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-family: Georgia, "Times New Roman", serif;
      font-size: clamp(38px, 6vw, 72px);
      font-weight: 400;
